import assert from 'node:assert/strict';
import { inArray } from 'drizzle-orm';
import { db, echoCreatorEntitlementsTable, echoUniversesTable } from '@workspace/db';

/** Only the exact synthetic identities generated by these PostgreSQL tests. */
export async function cleanupDisposableOwners(owners: readonly string[]) {
  const allowed = /^(?:ai-checkpoint-test-[a-f0-9-]{36}|echo-test-[a-f0-9-]{36}-[ab])$/;
  if (!owners.length || owners.some(owner => !allowed.test(owner))) {
    throw new Error('DISPOSABLE_TEST_OWNER_REQUIRED');
  }
  await db.transaction(async tx => {
    await tx.delete(echoUniversesTable).where(inArray(echoUniversesTable.ownerId, [...owners]));
    await tx.delete(echoCreatorEntitlementsTable).where(inArray(echoCreatorEntitlementsTable.ownerId, [...owners]));
    assert.equal((await tx.select().from(echoUniversesTable)
      .where(inArray(echoUniversesTable.ownerId, [...owners]))).length, 0);
    assert.equal((await tx.select().from(echoCreatorEntitlementsTable)
      .where(inArray(echoCreatorEntitlementsTable.ownerId, [...owners]))).length, 0);
  });
}
